INSERT INTO dilemma_categories (id, code, title, title_hindi, description, icon, prescription) VALUES (1, 'ANXIETY_OVERWHELM', 'Anxiety & Overwhelm', 'चिंता और व्याकुलता', 'When mind races with what-if scenarios, panic, and uncertainty about outcomes.', '🌊', 'Focus entirely on the present action; release attachment to outcomes. The mind is turbulent, but controlled by practice and detachment.');
INSERT INTO verse_dilemmas (dilemma_id, verse_id, takeaway) VALUES (1, 94, 'You have right only to action, never to fruits. Be not anxious about results.');
INSERT INTO verse_dilemmas (dilemma_id, verse_id, takeaway) VALUES (1, 61, 'Pleasure and pain come and go like seasons. Learn to endure them with equanimity.');
INSERT INTO verse_dilemmas (dilemma_id, verse_id, takeaway) VALUES (1, 268, 'Doubtless the mind is restless, O Arjuna, but it is mastered by constant practice and detachment.');
INSERT INTO verse_dilemmas (dilemma_id, verse_id, takeaway) VALUES (1, 689, 'Abandon all worries and surrender in trust. I shall deliver you from all despair.');
INSERT INTO dilemma_categories (id, code, title, title_hindi, description, icon, prescription) VALUES (2, 'BURNOUT_PROCRASTINATION', 'Burnout & Procrastination', 'थकावट और काम टालना', 'When motivation is depleted, tasks feel meaningless, and lethargy takes over.', '⚡', 'Action is superior to inaction. Perform your duty without ego-driven pressure, treating work as sacred dedication.');
INSERT INTO verse_dilemmas (dilemma_id, verse_id, takeaway) VALUES (2, 127, 'Perform your prescribed duty, for action is indeed better than inaction.');
INSERT INTO verse_dilemmas (dilemma_id, verse_id, takeaway) VALUES (2, 138, 'Constantly perform your duties without attachment; thus one attains the highest state.');
INSERT INTO verse_dilemmas (dilemma_id, verse_id, takeaway) VALUES (2, 180, 'He who sees inaction in action, and action in inaction, is truly wise among humans.');
INSERT INTO dilemma_categories (id, code, title, title_hindi, description, icon, prescription) VALUES (3, 'ANGER_RESENTMENT', 'Anger & Frustration', 'क्रोध और अशांति', 'When expectations are violated, leading to frustration, bitterness, and loss of composure.', '🔥', 'Trace anger back to attachment. Control the senses before anger clouds intellect and ruins peace.');
INSERT INTO verse_dilemmas (dilemma_id, verse_id, takeaway) VALUES (3, 109, 'Brooding on objects creates attachment; attachment breeds desire; unfulfilled desire sparks anger.');
INSERT INTO verse_dilemmas (dilemma_id, verse_id, takeaway) VALUES (3, 110, 'From anger arises delusion, from delusion loss of memory, and thereby ruin of intellect.');
INSERT INTO verse_dilemmas (dilemma_id, verse_id, takeaway) VALUES (3, 227, 'One who can withstand the impulses of lust and anger before leaving the body is truly joyful.');
INSERT INTO dilemma_categories (id, code, title, title_hindi, description, icon, prescription) VALUES (4, 'GRIEF_LOSS', 'Grief & Heartbreak', 'शोक और बिछोह', 'Coping with loss of loved ones, broken relationships, or shattered expectations.', '🕊️', 'The physical form is transient, but the soul is eternal, unkillable, and indestructible.');
INSERT INTO verse_dilemmas (dilemma_id, verse_id, takeaway) VALUES (4, 58, 'The wise grieve neither for the living nor for the departed.');
INSERT INTO verse_dilemmas (dilemma_id, verse_id, takeaway) VALUES (4, 67, 'The soul is never born, nor does it ever die; unborn, eternal, undying, it is not slain when the body dies.');
INSERT INTO verse_dilemmas (dilemma_id, verse_id, takeaway) VALUES (4, 69, 'Just as a person casts off worn-out garments and puts on new ones, the soul casts off worn-out bodies.');
INSERT INTO dilemma_categories (id, code, title, title_hindi, description, icon, prescription) VALUES (5, 'DECISION_PARALYSIS', 'Decision Paralysis & Confusion', 'दुविधा और अनिर्णय', 'Stuck between hard choices, fearing making the wrong move or harming others.', '⚖️', 'Consult your higher self, establish a one-pointed intellect (Vyavasayatmika Buddhi), and act with integrity.');
INSERT INTO verse_dilemmas (dilemma_id, verse_id, takeaway) VALUES (5, 54, 'My heart is weighed down by confusion; tell me decisively what is best for me.');
INSERT INTO verse_dilemmas (dilemma_id, verse_id, takeaway) VALUES (5, 88, 'The resolute intellect is one-pointed; the intellect of the indecisive is many-branched.');
INSERT INTO verse_dilemmas (dilemma_id, verse_id, takeaway) VALUES (5, 686, 'Reflect on this wisdom thoroughly, and then act as you choose.');
INSERT INTO dilemma_categories (id, code, title, title_hindi, description, icon, prescription) VALUES (6, 'PURPOSE_SWADHARMA', 'Finding Purpose (Swadharma)', 'स्वधर्म और जीवन का उद्देश्य', 'Questioning your path, comparing yourself to others, or feeling lost in career and life.', '🧭', 'Better is one’s own duty, though imperfect, than another’s duty well performed. Align action with your innate nature.');
INSERT INTO verse_dilemmas (dilemma_id, verse_id, takeaway) VALUES (6, 154, 'Better is one’s own duty, though devoid of merit, than the duty of another well performed.');
INSERT INTO verse_dilemmas (dilemma_id, verse_id, takeaway) VALUES (6, 669, 'By worshiping the Supreme through performance of one’s natural duty, a person achieves perfection.');
INSERT INTO verse_dilemmas (dilemma_id, verse_id, takeaway) VALUES (6, 670, 'One who performs duties dictated by natural inclination incurs no sin.');
